// AWI: diagnosa kalkulator sementara (hapus setelah dipakai)
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/calcdiag', array(
		'methods' => 'GET',
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function () {
			global $wpdb;
			$out = array();
			$kw = '/kalkul|calc|cicil|angsur|tenor|hemat|simulasi|kwh|km\/l/i';
			$sn = $wpdb->get_results("SELECT id, name, active, code FROM {$wpdb->prefix}snippets WHERE active=1");
			foreach ($sn as $s) {
				if (!preg_match($kw, $s->code)) continue;
				preg_match_all('/(?:BYD|Denza) [A-Z][A-Za-z0-9 .()\-]{1,34}/', $s->code, $m);
				$names = array_values(array_unique(array_map('trim', $m[0])));
				$out['snip'][] = array('id' => $s->id, 'name' => $s->name, 'len' => strlen($s->code), 'names' => array_slice($names, 0, 40), 'nums' => preg_match_all('/\b\d{3}e6\b|\b[1-9]\d{2}[.]?\d{3}[.]?000\b/', $s->code));
			}
			$ps = $wpdb->get_results("SELECT ID, post_type, post_name, post_content FROM {$wpdb->posts} WHERE post_status='publish' AND post_type IN ('page','post','model') AND post_content LIKE '%<script%'");
			foreach ($ps as $p) {
				if (!preg_match($kw, $p->post_content)) continue;
				preg_match_all('/(?:BYD|Denza) [A-Z][A-Za-z0-9 .()\-]{1,34}/', $p->post_content, $m);
				$sc = '';
				if (preg_match_all('#<script[^>]*>(.*?)</script>#s', $p->post_content, $s2)) $sc = implode(' ', $s2[1]);
				preg_match_all('/[\'"]?([a-z0-9]+)[\'"]?\s*:\s*\{[^{}]{0,200}?(?:p|price|harga|otr)\s*:\s*([0-9e.]+)/i', $sc, $arr, PREG_SET_ORDER);
				$out['posts'][] = array('id' => $p->ID, 'type' => $p->post_type, 'slug' => $p->post_name, 'scriptlen' => strlen($sc), 'names' => array_slice(array_values(array_unique(array_map('trim', $m[0]))), 0, 30), 'sample' => substr(preg_replace('/\s+/', ' ', $sc), 0, 600));
			}
			return $out;
		},
	));
});
